function ApplyDamageReductionStacks(player, stacks, duration)
    local aura = player:GetAura(699100)
    if not aura then
        aura = player:AddAura(699100, player)
    end
    if aura then
        aura:SetStackAmount(stacks)
        aura:SetDuration(duration)
    end
end

